    private static boolean isOverdue(Claim c, Person p, Sheet sheet, LocalDate today) {
        return c.getStatus().isOpen() && today != null && !c.isDeferredOn(today) && c.getDueBy() != null
                && ClaimService.lateFrom(c, p, sheet).isBefore(today);
    }

